def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    def opp_def_rate(start):
        total = n - start
        if total <= 0:
            return 0.0
        d = 0
        for i in range(start, n):
            if history[i][1] == 'D':
                d += 1
        return d / total

    op_def = sum(1 for h in history if h[1] == 'D')
    my_def = sum(1 for h in history if h[0] == 'D')
    last_me, last_op = history[-1]

    # Opponent never defected: preserve mutual cooperation, exploit only at the very end.
    if op_def == 0:
        if n >= 99:
            return 'D'
        return 'C'

    # If opponent has been almost perfectly cooperative with a single isolated defection,
    # forgive and keep cooperating (maybe one short retaliation).
    if op_def == 1:
        # find where the defection happened
        idx = 0
        for i in range(n):
            if history[i][1] == 'D':
                idx = i
                break
        # If it was long ago and they've cooperated since, just cooperate.
        if n - idx >= 3:
            if n >= 98:
                return 'D'
            return 'C'
        # Recent single defection: retaliate once then forgive.
        if last_me == 'D':
            return 'C'
        if n >= 98:
            return 'D'
        return 'D'

    # Count defections in recent windows.
    w1 = min(8, n)
    recent_def = 0
    for i in range(n - w1, n):
        if history[i][1] == 'D':
            recent_def += 1
    recent_rate = recent_def / w1

    w2 = min(20, n)
    mid_def = 0
    for i in range(n - w2, n):
        if history[i][1] == 'D':
            mid_def += 1
    mid_rate = mid_def / w2

    overall_rate = op_def / n

    # Trailing opponent defection streak.
    opp_def_streak = 0
    for i in range(n - 1, -1, -1):
        if history[i][1] == 'D':
            opp_def_streak += 1
        else:
            break

    # Trailing opponent cooperation streak.
    opp_c_streak = 0
    for i in range(n - 1, -1, -1):
        if history[i][1] == 'C':
            opp_c_streak += 1
        else:
            break

    rounds_left = 100 - n

    # Endgame exploitation: last couple rounds, defect if opponent likely to cooperate.
    if rounds_left <= 2:
        if last_op == 'C' and mid_rate < 0.5:
            return 'D'
        return 'D'

    # Very cooperative opponent overall: keep cooperating, small occasional test.
    if overall_rate <= 0.1 and mid_rate <= 0.15:
        if n >= 96 and rng.random() < 0.6:
            return 'D'
        return 'C'

    # Highly defective opponent: defect mostly, but still try occasional repairs.
    if overall_rate >= 0.6 or mid_rate >= 0.7:
        if opp_def_streak >= 4 and rng.random() < 0.15:
            return 'C'
        return 'D'

    # If recent window shows mostly cooperation, cooperate (preserve mutual CC).
    if recent_rate <= 0.2:
        # Occasional opportunistic defection, but rare and not near endgame yet.
        if n >= 94 and rng.random() < 0.4:
            return 'D'
        return 'C'

    # Mixed regimes: use forgiving tit-for-tat with recovery from retaliation chains.

    # If opponent just cooperated:
    if last_op == 'C':
        # If we've been defecting a lot more than opponent, return to cooperation.
        if my_def > op_def + 2:
            return 'C'
        # If we've been cooperating and opponent shows some defection tendency,
        # occasional probe (but keep mostly cooperative).
        if rng.random() < 0.06 and rounds_left > 12:
            return 'D'
        return 'C'

    # Opponent just defected. Decide retaliation vs forgiveness.
    # If opponent has been mostly cooperative (low overall), forgive quickly.
    if overall_rate <= 0.2:
        # Retaliate once if we cooperated last; else return to cooperation.
        if last_me == 'C':
            return 'D'
        return 'C'

    # If they are in a long defection streak, retaliate.
    if opp_def_streak >= 3:
        # But try to break mutual defection loops occasionally.
        my_def_streak = 0
        for i in range(n - 1, -1, -1):
            if history[i][0] == 'D':
                my_def_streak += 1
            else:
                break
        if my_def_streak >= 3 and rng.random() < 0.2 and rounds_left > 5:
            return 'C'
        return 'D'

    # Short defection burst by opponent: one-round retaliation then repair.
    if last_me == 'D':
        # We already retaliated; go back to cooperation to invite repair.
        if recent_rate <= 0.4:
            return 'C'
        if rng.random() < 0.4:
            return 'C'
        return 'D'

    # We cooperated and they defected: retaliate once.
    return 'D'
